static double call(int fn, double a, double b, int n)
{
    switch (fn)
    {
    case 0: return sqrt(a);
    case 1: return sin(a);
    case 2: return cos(a);
    case 3: return tan(a);
    case 4: return atan(a);
    case 5: return asin(a);
    case 6: return acos(a);
    case 7: return exp(a);
    case 8: return log(a);
    case 9: return log10(a);
    case 10: return floor(a);
    case 11: return ceil(a);
    case 12: return fabs(a);
    case 13: return sinh(a);
    case 14: return cosh(a);
    case 15: return tanh(a);
    case 16: return atan2(a, b);
    case 17: return pow(a, b);
    case 18: return fmod(a, b);
    }
    return ldexp(a, n);
}

/* distance of two doubles in units of the last place */
static void key(Dbl x, unsigned long *hi, unsigned long *lo)
{
    *hi = x.w[1];
    *lo = x.w[0];
    if (*hi & 0x80000000UL)
    {
        *hi = ~*hi;
        *lo = ~*lo;
    }
    else
        *hi |= 0x80000000UL;
}

static unsigned long ulps(Dbl x, Dbl y)
{
    unsigned long xh, xl, yh, yl, t;

    key(x, &xh, &xl);
    key(y, &yh, &yl);
    if (xh < yh || (xh == yh && xl < yl))
    {
        t = xh; xh = yh; yh = t;
        t = xl; xl = yl; yl = t;
    }
    t = xl - yl;
    xh -= yh + (xl < yl ? 1 : 0);
    return xh ? 0xFFFFFFFFUL : t;
}

static void table_tests(void)
{
    unsigned i;
    Dbl a, b, r, g;
    unsigned long u;

    for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
    {
        a.w[0] = cases[i].al;
        a.w[1] = cases[i].ah;
        b.w[0] = cases[i].bl;
        b.w[1] = cases[i].bh;
        r.w[0] = cases[i].rl;
        r.w[1] = cases[i].rh;
        g.d = call(cases[i].fn, a.d, b.d,
                   (int)cases[i].bl);
        u = ulps(g, r);
        if (u > cases[i].tol)
        {
            failed++;
            printf("case %u fn %d: %lu ulps\n", i,
                   cases[i].fn, u);
        }
    }
}

static void misc_tests(void)
{
    int e;
    double ip, fr;
    Dbl z, one;

    z.d = 0.0;
    one.d = 1.0;
    fr = frexp(8.0, &e);
    CHECK(fr == 0.5 && e == 4);
    fr = frexp(-3.0, &e);
    CHECK(fr == -0.75 && e == 2);
    fr = frexp(0.0, &e);
    CHECK(fr == 0.0 && e == 0);
    fr = frexp(1.0, &e);
    CHECK(fr == 0.5 && e == 1);
    fr = modf(3.25, &ip);
    CHECK(fr == 0.25 && ip == 3.0);
    fr = modf(-3.25, &ip);
    CHECK(fr == -0.25 && ip == -3.0);
    CHECK(_finite(1.0) && _finite(0.0));
    CHECK(!_finite(one.d / z.d) && !_finite(z.d / z.d));
    CHECK(_isnan(z.d / z.d) && !_isnan(1.0));
    CHECK(_copysign(2.0, -1.0) == -2.0);
    CHECK(_copysign(-2.0, 1.0) == 2.0);
    CHECK(_chgsign(2.0) == -2.0);
    CHECK(_isnan(sqrt(-1.0)));
    CHECK(_isnan(log(-1.0)));
    CHECK(!_finite(log(0.0)));
    CHECK(!_finite(exp(1000.0)));
    CHECK(!_finite(pow(0.0, -1.0)));
    CHECK(_isnan(pow(-8.0, 0.5)));
    CHECK(_isnan(asin(2.0)));
    _clearfp();
    CHECK(_statusfp() == 0);
}

void mainCRTStartup(void)
{
    table_tests();
    misc_tests();
    if (failed)
    {
        printf("\r\nMATH: fail %d\r\n", failed);
        exit(1);
    }
    printf("\r\nMATH: ok\r\n");
    exit(0);
}
